=head2 Google::Cloud::Translation::V3beta1::TranslationService::TranslateTextGlossaryConfig

Configures which glossary should be used for a specific target language,
and defines options for applying that glossary.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->glossary() >> / C<< $msg->glossary($value) >>

Type: C<String>

Required. Specifies the glossary used for this translation. Use
this format: projects/*/locations/*/glossaries/*

=item * C<< $msg->ignore_case() >> / C<< $msg->ignore_case($value) >>

Type: C<Bool>

Optional. Indicates match is case-insensitive.
Default value is false if missing.

=item * C<< $msg->contextual_translation_enabled() >> / C<< $msg->contextual_translation_enabled($value) >>

Type: C<Bool>

Optional. If set to true, the glossary will be used for contextual
translation.

=back

