Optional. Glossary to be applied. The glossary must be within the same
region (have the same location-id) as the model, otherwise an
INVALID_ARGUMENT (400) error is returned.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Translation::V3beta1::TranslationService::TranslateDocumentRequest::LabelsEntry>)

Optional. The labels with user-defined metadata for the request.

Label keys and values can be no longer than 63 characters (Unicode
codepoints), can only contain lowercase letters, numeric characters,
underscores and dashes. International characters are allowed. Label values
are optional. Label keys must start with a letter.

See https://cloud.google.com/translate/docs/advanced/labels for more
information.

=item * C<< $msg->customized_attribution() >> / C<< $msg->customized_attribution($value) >>

Type: C<String>

Optional. This flag is to support user customized attribution.
If not provided, the default is `Machine Translated by Google`.
Customized attribution should follow rules in
https://cloud.google.com/translate/attribution#attribution_and_logos

=item * C<< $msg->is_translate_native_pdf_only() >> / C<< $msg->is_translate_native_pdf_only($value) >>

Type: C<Bool>

Optional. is_translate_native_pdf_only field for external customers.
If true, the page limit of online native pdf translation is 300 and only
native pdf pages will be translated.

=item * C<< $msg->enable_shadow_removal_native_pdf() >> / C<< $msg->enable_shadow_removal_native_pdf($value) >>

Type: C<Bool>

Optional. If true, use the text removal server to remove the shadow text on
background image for native pdf translation.
Shadow removal feature can only be enabled when
is_translate_native_pdf_only: false && pdf_native_only: false

=item * C<< $msg->enable_rotation_correction() >> / C<< $msg->enable_rotation_correction($value) >>

Type: C<Bool>

Optional. If true, enable auto rotation correction in DVS.

=back

